  tianfu: arrival(P.tianfu, 0, 240),
  chunxi: arrival(P.chunxi, -80, 130),
  taikooli: arrival(P.taikooli, -90, 90),
  kuanzhai: arrival(P.kuanzhai, -100, 60),
  renminpark: arrival(P.renminpark, -120, 130),
  wenshu: arrival(P.wenshu, -70, 110),
