const ISLAND_BOUNDS = (() => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of COASTLINE) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return { minX, maxX, minZ, maxZ, sidewalkHeight: 0.22, parkPavingHeight: 0.26, waterLevel: -1.6 };
})();

/** Street & place name at any world (x, z): the nearest roads of the real street centreline */
function getLocationLabel(x, z) {
  for (const lm of CITY_LANDMARKS) {
    if (Math.hypot(x - lm.x, z - lm.z) < 80) {
      const near = nearestRoads(x, z, 120);
      return `${lm.name}${near.length ? ` · ${near[0].road.short}` : ''}`;
    }
  }
  const b = blockAt(x, z);
  if (b && b.parkName && b.park > 0.6) return b.parkName;
  if (!onLand(x, z)) return '成都';
  const near = nearestRoads(x, z, 160);
  const a = near[0];
  const c = a && near.find((r) => r.horizontal !== a.horizontal && r.dist < a.dist + 25);
  if (a && c) return `${a.road.short} · ${c.road.short}`;
  if (a) return a.road.name;
  return barriAt(x, z).name;
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds:
// the "avenue" phase (traffic along grid x: 蜀都大道, 东大街…) green until avenueAmber, amber until avenueRed; the cross
// phase (along grid z: 人民南路, 红星路…) green from avenueRed until streetAmber, amber until the end of the cycle.
const SIGNAL_TIMING = { cycle: 80, avenueAmber: 36, avenueRed: 40, streetAmber: 76, walk: 9 };

function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

